9: 
10: const CONFIGURE_MAX_POLLS: usize = 100_000;
11: const IRQ_DRAIN_LIMIT: usize = 16;
12: 
13: const DATA_PORT: u16 = 0x60;
14: const STATUS_PORT: u16 = 0x64;
15: const OUTPUT_BUFFER_FULL: u8 = 1 << 0;
16: const AUXILIARY_OUTPUT: u8 = 1 << 5;
17: const TIMEOUT_ERROR: u8 = 1 << 6;
18: const PARITY_ERROR: u8 = 1 << 7;
