20: /// Enable the controller's keyboard IRQ after bounded status checks.
21: ///
22: /// Returns false when the legacy controller does not respond within the bounded
23: /// waits. The caller must keep the I/O APIC route masked until the handler is
24: /// registered and this setup has succeeded.
25: pub fn initialize_interrupts() -> bool {
26:     // SAFETY: This privileged driver owns the legacy controller ports during
27:     // single-CPU bootstrap; all waits are bounded and no other reader is active.
28:     unsafe {
29:         for _ in 0..IRQ_DRAIN_LIMIT {
30:             if read_u8(STATUS_PORT) & OUTPUT_BUFFER_FULL == 0 {
31:                 break;
32:             }
33:             let _ = read_u8(DATA_PORT);
34:         }
35:         if !wait_input_empty() {
36:             return false;
37:         }
38:         write_u8(STATUS_PORT, 0x20);
39:         if !wait_output_full() {
40:             return false;
41:         }
42:         let mut config = read_u8(DATA_PORT);
43:         config |= 1 << 1;
44:         config &= !(1 << 4);
45:         if !wait_input_empty() {
46:             return false;
47:         }
48:         write_u8(STATUS_PORT, 0x60);
49:         if !wait_input_empty() {
50:             return false;
51:         }
52:         write_u8(DATA_PORT, config);
53:         if !wait_input_empty() {
54:             return false;
55:         }
56:         write_u8(STATUS_PORT, 0xae);
57:         wait_input_empty()
58:     }
59: }
