61: fn wait_input_empty() -> bool {
62:     for _ in 0..CONFIGURE_MAX_POLLS {
63:         // SAFETY: Caller runs at CPL 0 and this is the controller status port.
64:         if unsafe { read_u8(STATUS_PORT) } & (1 << 1) == 0 {
65:             return true;
66:         }
67:         core::hint::spin_loop();
68:     }
69:     false
70: }
71: 
72: fn wait_output_full() -> bool {
73:     for _ in 0..CONFIGURE_MAX_POLLS {
74:         // SAFETY: Caller runs at CPL 0 and this is the controller status port.
75:         if unsafe { read_u8(STATUS_PORT) } & OUTPUT_BUFFER_FULL != 0 {
76:             return true;
77:         }
78:         core::hint::spin_loop();
79:     }
80:     false
81: }
