83: /// IRQ1 handler: drain a bounded number of bytes into the raw input queue.
84: pub extern "C" fn irq_handler() {
85:     let mut received = false;
86:     for _ in 0..IRQ_DRAIN_LIMIT {
87:         // SAFETY: IRQ1 is registered only after controller setup. The handler is
88:         // the sole controller-data consumer while maskable interrupts are off.
89:         let status = unsafe { read_u8(STATUS_PORT) };
90:         if status & OUTPUT_BUFFER_FULL == 0 {
91:             break;
92:         }
93:         // SAFETY: Status reported an available controller output byte.
94:         let byte = unsafe { read_u8(DATA_PORT) };
95:         if status & (AUXILIARY_OUTPUT | TIMEOUT_ERROR | PARITY_ERROR) == 0 {
96:             received |= rustix_kernel::input::KEYBOARD_INPUT.try_push(byte);
97:         }
98:     }
99:     if received {
100:         rustix_kernel::input::INPUT_EVENT_PENDING
101:             .store(true, core::sync::atomic::Ordering::Release);
102:     }
103:     super::apic::end_of_interrupt();
104: }
