114: /// are consumed and discarded so they cannot leave the output buffer blocked.
115: /// Returns `None` when no keyboard byte is ready.
116: pub fn try_read_scancode() -> Option<u8> {
117:     // SAFETY: The x86_64 platform driver is privileged and owns these legacy
118:     // controller ports. Reads are non-blocking and only performed when ready.
119:     unsafe {
120:         let status = read_u8(STATUS_PORT);
121:         if status & OUTPUT_BUFFER_FULL == 0 {
122:             return None;
123:         }
124: 
125:         let byte = read_u8(DATA_PORT);
126:         if status & (AUXILIARY_OUTPUT | TIMEOUT_ERROR | PARITY_ERROR) != 0 {
127:             return None;
128:         }
129:         Some(byte)
130:     }
131: }

