87: /// local APIC LVT entries, then enables the local APIC's software interface.
88: /// The ISA IRQ0 route is resolved and range-checked here, but remains masked.
89: ///
90: /// # Safety
91: /// Must execute at CPL 0 on the bootstrap processor with maskable interrupts
92: /// disabled. `local_apic_virtual` and `io_apic_virtual` must be page-aligned
93: /// virtual addresses of valid, writable, supervisor, NX, UC mappings of the
94: /// complete physical pages identified by `madt`. Those mappings must remain
95: /// valid for all subsequent calls. No other CPU or code may access or reprogram
96: /// these controllers concurrently. `madt` must be a validated ACPI MADT.
97: pub unsafe fn initialize(
98:     madt: &Madt,
99:     local_apic_virtual: u64,
100:     io_apic_virtual: u64,
101:     bootstrap_apic_id: u8,
102: ) -> Result<(), ApicError> {
103:     if !interrupts_are_disabled() {
104:         return Err(ApicError::InterruptsEnabled);
105:     }
106:     if INITIALIZED.load(Ordering::Acquire) {
107:         return Err(ApicError::AlreadyInitialized);
108:     }
109: 
110:     TIMER_CONFIGURED.store(false, Ordering::Relaxed);
111:     IO_APIC_GSI_BASE.store(0, Ordering::Relaxed);
112:     IO_APIC_MAX_REDIRECTION.store(0, Ordering::Relaxed);
113:     for route in &ISA_ROUTE_LOW_REGISTERS {
114:         route.store(0, Ordering::Relaxed);
115:     }
116:     LOCAL_APIC_VIRTUAL.store(0, Ordering::Relaxed);
117:     IO_APIC_VIRTUAL.store(0, Ordering::Relaxed);
118:     TIMER_LOW_REGISTER.store(0, Ordering::Relaxed);
