354:     // Install the destination first, then the masked low dword so no transient
355:     // unmasked route can be observed.
356:     unsafe {
357:         io_apic_write(io_apic_virtual, high_register, u32::from(destination) << 24);
358:         io_apic_write(io_apic_virtual, low_register, route_low);
359:         io::write_u8(PIT_COMMAND, PIT_RATE_GENERATOR_LOHI);
360:         io::write_u8(PIT_CHANNEL_0, divisor as u8);
361:         io::write_u8(PIT_CHANNEL_0, (divisor >> 8) as u8);
