134:         vendor,
135:         max_basic_leaf: basic.eax,
136:         max_extended_leaf: extended.eax,
137:         has_sse2: basic_features.is_some_and(|features| features.edx & (1 << 26) != 0),
138:         has_nx,
139:         nx_enabled,
