317:     physical_start
318:         .checked_add(length)
319:         .ok_or(AcpiReadError::InvalidPhysicalExtent)?;
320:     reader
321:         .read_rsdp(physical_start, output)
322:         .map_err(AcpiReadError::Reader)
323: }
