325: fn read_physical<R: AcpiPhysicalReader>(
326:     reader: &mut R,
327:     physical_start: u64,
328:     output: &mut [u8],
329: ) -> Result<(), AcpiReadError<R::Error>> {
330:     let length = u64::try_from(output.len()).map_err(|_| AcpiReadError::InvalidPhysicalExtent)?;
331:     physical_start
332:         .checked_add(length)
333:         .ok_or(AcpiReadError::InvalidPhysicalExtent)?;
334:     reader
335:         .read(physical_start, output)
336:         .map_err(AcpiReadError::Reader)
337: }
