339: fn checked_sdt_length<E>(header: &[u8]) -> Result<usize, AcpiReadError<E>> {
340:     if header.len() < SDT_HEADER_SIZE {
341:         return Err(AcpiReadError::Parse(AcpiError::StructureTooShort));
342:     }
343:     let length = read_u32(header, 4) as usize;
344:     if length < SDT_HEADER_SIZE {
345:         return Err(AcpiReadError::Parse(AcpiError::InvalidSdtLength));
346:     }
347:     if length > MAX_ACPI_STRUCTURE_SIZE {
348:         return Err(AcpiReadError::Parse(AcpiError::StructureTooLarge));
349:     }
350:     Ok(length)
351: }
