558:     /// Resolve an ISA IRQ source using its MADT override or ISA defaults.
559:     /// Conforming ISA flags default to active-high, edge-triggered delivery.
560:     pub fn resolve_isa_interrupt(&self, source: u8) -> ResolvedIsaInterrupt {
561:         let override_entry = self
562:             .interrupt_overrides()
563:             .find(|entry| entry.bus == 0 && entry.source == source);
564:         let (global_system_interrupt, flags) = override_entry
565:             .map(|entry| (entry.global_system_interrupt, entry.flags))
566:             .unwrap_or((u32::from(source), 0));
567:         let polarity = match flags & 0x3 {
568:             3 => InterruptPolarity::ActiveLow,
569:             _ => InterruptPolarity::ActiveHigh,
570:         };
571:         let trigger = match (flags >> 2) & 0x3 {
572:             3 => InterruptTrigger::Level,
573:             _ => InterruptTrigger::Edge,
574:         };
575:         ResolvedIsaInterrupt {
576:             source,
577:             global_system_interrupt,
578:             polarity,
579:             trigger,
580:         }
581:     }
582: }
