192: impl<'a> RootPointerTable<'a> {
193:     pub fn parse(table: Sdt<'a>) -> Result<Self, AcpiError> {
194:         let entry_width = match table.signature {
195:             [b'R', b'S', b'D', b'T'] => 4,
196:             [b'X', b'S', b'D', b'T'] => 8,
197:             _ => return Err(AcpiError::NotRootPointerTable),
198:         };
199:         let payload_length = table.bytes.len() - SDT_HEADER_SIZE;
200:         if payload_length % entry_width != 0 {
201:             return Err(AcpiError::InvalidRootPointerTableLength);
202:         }
203:         let entry_count = payload_length / entry_width;
204:         if entry_count > MAX_ACPI_ROOT_ENTRIES {
205:             return Err(AcpiError::TooManyRootPointers);
206:         }
207:         let pointers = &table.bytes[SDT_HEADER_SIZE..];
208:         for index in 0..entry_count {
209:             let offset = index * entry_width;
210:             let address = if entry_width == 4 {
211:                 read_u32(pointers, offset) as u64
212:             } else {
213:                 read_u64(pointers, offset)
214:             };
215:             if address == 0 {
216:                 return Err(AcpiError::NullRootPointer);
217:             }
218:         }
219:         Ok(Self {
220:             bytes: pointers,
221:             entry_width,
222:             entry_count,
223:         })
224:     }
