408: impl Madt {
409:     /// Parse the known xAPIC MADT records into bounded owned arrays.
410:     ///
411:     /// Unknown record types are skipped after validating their common header.
412:     /// x2APIC processor records are rejected because this parser does not yet
413:     /// establish x2APIC mode or destination-ID policy.
414:     pub fn parse(table: Sdt<'_>) -> Result<Self, AcpiError> {
415:         if table.signature != *b"APIC" {
416:             return Err(AcpiError::NotMadt);
417:         }
418:         if table.bytes.len() < MADT_FIXED_SIZE {
419:             return Err(AcpiError::InvalidMadtLength);
420:         }
421: 
422:         let mut madt = Self {
423:             local_apic_address: read_u32(table.bytes, SDT_HEADER_SIZE) as u64,
424:             flags: read_u32(table.bytes, SDT_HEADER_SIZE + 4),
425:             local_apics: [None; MAX_LOCAL_APICS],
426:             local_apic_count: 0,
427:             io_apics: [None; MAX_IO_APICS],
428:             io_apic_count: 0,
429:             interrupt_overrides: [None; MAX_INTERRUPT_OVERRIDES],
430:             interrupt_override_count: 0,
431:         };
432: 
433:         let mut local_apic_address_override_seen = false;
434:         let mut offset = MADT_FIXED_SIZE;
435:         let mut entry_count = 0;
436:         while offset < table.bytes.len() {
437:             if table.bytes.len() - offset < 2 {
438:                 return Err(AcpiError::InvalidMadtEntryLength);
439:             }
440:             let entry_type = table.bytes[offset];
441:             let entry_length = table.bytes[offset + 1] as usize;
442:             if entry_length < 2 || entry_length > table.bytes.len() - offset {
443:                 return Err(AcpiError::InvalidMadtEntryLength);
444:             }
445:             entry_count += 1;
446:             if entry_count > MAX_MADT_ENTRIES {
447:                 return Err(AcpiError::TooManyMadtEntries);
448:             }
449: 
450:             let entry = &table.bytes[offset..offset + entry_length];
451:             match entry_type {
452:                 0 => {
453:                     require_entry_length(entry_length, 8)?;
454:                     let processor_uid = entry[2];
455:                     let apic_id = entry[3];
456:                     let flags = read_u32(entry, 4);
457:                     if flags & !0x3 != 0 {
458:                         return Err(AcpiError::InvalidLocalApicFlags);
459:                     }
460:                     if madt
461:                         .local_apics()
462:                         .any(|cpu| cpu.processor_uid == processor_uid || cpu.apic_id == apic_id)
463:                     {
464:                         return Err(AcpiError::DuplicateLocalApic);
465:                     }
466:                     push(
467:                         &mut madt.local_apics,
468:                         &mut madt.local_apic_count,
469:                         LocalApic {
470:                             processor_uid,
471:                             apic_id,
472:                             flags,
473:                         },
474:                     )?;
475:                 }
476:                 1 => {
477:                     require_entry_length(entry_length, 12)?;
478:                     let apic_id = entry[2];
479:                     let physical_address = read_u32(entry, 4);
480:                     if physical_address == 0 || physical_address & 0xfff != 0 {
481:                         return Err(AcpiError::InvalidIoApicAddress);
482:                     }
483:                     if madt.io_apics().any(|io_apic| io_apic.apic_id == apic_id) {
484:                         return Err(AcpiError::DuplicateIoApicId);
485:                     }
486:                     push(
487:                         &mut madt.io_apics,
488:                         &mut madt.io_apic_count,
489:                         IoApic {
490:                             apic_id,
491:                             physical_address,
492:                             global_system_interrupt_base: read_u32(entry, 8),
493:                         },
494:                     )?;
495:                 }
496:                 2 => {
497:                     require_entry_length(entry_length, 10)?;
498:                     let bus = entry[2];
499:                     let source = entry[3];
500:                     let flags = read_u16(entry, 8);
501:                     if flags & !0x000f != 0 || flags & 0x3 == 0x2 || (flags >> 2) & 0x3 == 0x2 {
502:                         return Err(AcpiError::InvalidInterruptOverrideFlags);
503:                     }
504:                     if madt.interrupt_overrides().any(|override_entry| {
505:                         override_entry.bus == bus && override_entry.source == source
506:                     }) {
507:                         return Err(AcpiError::DuplicateInterruptOverride);
508:                     }
509:                     push(
510:                         &mut madt.interrupt_overrides,
511:                         &mut madt.interrupt_override_count,
512:                         InterruptSourceOverride {
513:                             bus,
514:                             source,
515:                             global_system_interrupt: read_u32(entry, 4),
516:                             flags,
517:                         },
518:                     )?;
519:                 }
520:                 5 => {
521:                     require_entry_length(entry_length, 12)?;
522:                     if local_apic_address_override_seen {
523:                         return Err(AcpiError::DuplicateLocalApicAddressOverride);
524:                     }
525:                     local_apic_address_override_seen = true;
526:                     madt.local_apic_address = read_u64(entry, 4);
527:                 }
528:                 9 => return Err(AcpiError::UnsupportedMadtEntryType(entry_type)),
529:                 _ => {}
530:             }
531:             offset += entry_length;
532:         }
533:         if madt.local_apic_address == 0 || madt.local_apic_address & 0xfff != 0 {
534:             return Err(AcpiError::InvalidLocalApicAddress);
535:         }
536: 
537:         Ok(madt)
538:     }
