540:     pub fn local_apics(&self) -> impl Iterator<Item = LocalApic> + '_ {
541:         self.local_apics[..self.local_apic_count]
542:             .iter()
543:             .filter_map(|entry| *entry)
544:     }
545: 
546:     pub fn io_apics(&self) -> impl Iterator<Item = IoApic> + '_ {
547:         self.io_apics[..self.io_apic_count]
548:             .iter()
549:             .filter_map(|entry| *entry)
550:     }
551: 
552:     pub fn interrupt_overrides(&self) -> impl Iterator<Item = InterruptSourceOverride> + '_ {
553:         self.interrupt_overrides[..self.interrupt_override_count]
554:             .iter()
555:             .filter_map(|entry| *entry)
556:     }
