584: fn require_entry_length(actual: usize, expected: usize) -> Result<(), AcpiError> {
585:     if actual == expected {
586:         Ok(())
587:     } else {
588:         Err(AcpiError::InvalidMadtEntryLength)
589:     }
590: }
