592: fn push<T: Copy, const N: usize>(
593:     entries: &mut [Option<T>; N],
594:     count: &mut usize,
595:     value: T,
596: ) -> Result<(), AcpiError> {
597:     let Some(slot) = entries.get_mut(*count) else {
598:         return Err(AcpiError::MadtCapacityExceeded);
599:     };
600:     *slot = Some(value);
601:     *count += 1;
602:     Ok(())
603: }
