605: fn checksum_is_valid(bytes: &[u8]) -> bool {
606:     bytes.iter().fold(0u8, |sum, byte| sum.wrapping_add(*byte)) == 0
607: }
608: 
609: fn read_u16(bytes: &[u8], offset: usize) -> u16 {
610:     u16::from_le_bytes([bytes[offset], bytes[offset + 1]])
611: }
612: 
613: fn read_u32(bytes: &[u8], offset: usize) -> u32 {
614:     u32::from_le_bytes([
615:         bytes[offset],
616:         bytes[offset + 1],
617:         bytes[offset + 2],
618:         bytes[offset + 3],
619:     ])
620: }
621: 
622: fn read_u64(bytes: &[u8], offset: usize) -> u64 {
623:     u64::from_le_bytes([
624:         bytes[offset],
625:         bytes[offset + 1],
626:         bytes[offset + 2],
627:         bytes[offset + 3],
628:         bytes[offset + 4],
629:         bytes[offset + 5],
630:         bytes[offset + 6],
631:         bytes[offset + 7],
632:     ])
633: }
