644:     fn set_checksum(bytes: &mut [u8], checksum_offset: usize, covered_length: usize) {
645:         bytes[checksum_offset] = 0;
646:         let sum = bytes[..covered_length]
647:             .iter()
648:             .fold(0u8, |sum, byte| sum.wrapping_add(*byte));
649:         bytes[checksum_offset] = 0u8.wrapping_sub(sum);
650:     }
