652:     fn make_sdt(signature: [u8; 4], body: &[u8]) -> std::vec::Vec<u8> {
653:         let length = 36 + body.len();
654:         let mut bytes = std::vec![0; length];
655:         bytes[..4].copy_from_slice(&signature);
656:         bytes[4..8].copy_from_slice(&(length as u32).to_le_bytes());
657:         bytes[8] = 1;
658:         bytes[10..16].copy_from_slice(b"RUSTIX");
659:         bytes[16..24].copy_from_slice(b"RUSTIX01");
660:         bytes[24..28].copy_from_slice(&1u32.to_le_bytes());
661:         bytes[28..32].copy_from_slice(b"RUST");
662:         bytes[32..36].copy_from_slice(&1u32.to_le_bytes());
663:         bytes[36..].copy_from_slice(body);
664:         set_checksum(&mut bytes, 9, length);
665:         bytes
