668:     #[derive(Default)]
669:     struct FakeReader {
670:         regions: std::vec::Vec<(u64, std::vec::Vec<u8>)>,
671:         fail_address: Option<u64>,
672:     }
673: 
674:     impl FakeReader {
675:         fn add_region(&mut self, address: u64, bytes: std::vec::Vec<u8>) {
676:             self.regions.push((address, bytes));
677:         }
678:     }
