680:     // The fixture regions stand in for memory-map-validated, readable ACPI extents.
681:     unsafe impl AcpiPhysicalReader for FakeReader {
682:         type Error = &'static str;
683: 
684:         fn read(&mut self, physical_start: u64, output: &mut [u8]) -> Result<(), Self::Error> {
685:             if self.fail_address == Some(physical_start) {
686:                 return Err("injected read failure");
687:             }
688:             for (base, bytes) in &self.regions {
689:                 let Some(offset) = physical_start.checked_sub(*base) else {
690:                     continue;
691:                 };
692:                 let Ok(offset) = usize::try_from(offset) else {
693:                     continue;
694:                 };
695:                 let Some(end) = offset.checked_add(output.len()) else {
696:                     continue;
697:                 };
698:                 if end <= bytes.len() {
699:                     output.copy_from_slice(&bytes[offset..end]);
700:                     return Ok(());
701:                 }
702:             }
703:             Err("unmapped fixture address")
704:         }
705:     }
