711:             bytes[9..15].copy_from_slice(b"RUSTIX");
712:             bytes[15] = 2;
713:             bytes[16..20].copy_from_slice(&0x7000u32.to_le_bytes());
714:             bytes[20..24].copy_from_slice(&36u32.to_le_bytes());
715:             bytes[24..32].copy_from_slice(&root_address.to_le_bytes());
716:             set_checksum(&mut bytes, 8, RSDP_V1_SIZE);
717:             let length = bytes.len();
718:             set_checksum(&mut bytes, 32, length);
719:             bytes
720:         } else {
