11: pub static UART_INPUT: ByteRing<INPUT_QUEUE_CAPACITY> = ByteRing::new();
12: pub static KEYBOARD_INPUT: ByteRing<INPUT_QUEUE_CAPACITY> = ByteRing::new();
13: pub static INPUT_EVENT_PENDING: core::sync::atomic::AtomicBool =
14:     core::sync::atomic::AtomicBool::new(false);
