28:     pub const fn new() -> Self {
29:         Self {
30:             bytes: [const { AtomicU8::new(0) }; CAPACITY],
31:             head: AtomicUsize::new(0),
32:             tail: AtomicUsize::new(0),
33:             head_index: AtomicUsize::new(0),
